  '场地': 'venue',
  '设备': 'equipment',
  '人员': 'person',
};

function emptyStore(): Store {
  return {
    version: 1,
    resourceSeq: 0,
    bookingSeq: 0,
    seriesSeq: 0,
    waitlistSeq: 0,
    closureSeq: 0,
    batchSeq: 0,
    resources: [],
    bookings: [],
