780	    ['EXDATE 列表含空项', w('RRULE:FREQ=WEEKLY;COUNT=2\nEXDATE:20261012T100000,\n'), /空的时间值/],
781	  ];
782	  for (const [name, file, pattern] of cases) {
783	    const r = importBizFail(df, file, ['R0001'], `重复负例：${name}`);
784	    assert.match(r.stderr, pattern, `重复负例：${name}`);
785	  }
786	  assert.equal(readStore(df).bookings.length, 0, '负例不产生预约');
787	  assert.equal(readStore(df).seriesSeq, 0, '负例不产生系列');
788	
789	  // 展开越出 9999 年：9999-12-27 的第 2 周发生落入 10000 年
790	  const edge = writeIcal(
791	    dir,
792	    'edge.ics',
793	    ical(event('edge', '99991227T100000', '99991227T110000', 'RRULE:FREQ=WEEKLY;COUNT=2\n')),
794	  );
795	  const rEdge = importBizFail(df, edge, ['R0001'], '展开越出年份');
796	  assert.match(rEdge.stderr, /超出四位年份范围/);
797	});
