799	// ---------------------------------------------------------------------------
800	// 21. 混合文件：独立 + 重复 + 重放，仅新事件展开校验；一次原子保存
801	// ---------------------------------------------------------------------------
802	
803	test('混合独立/重复/重放事件：新系列与新预约原子保存，重放不计数', (t) => {
804	  const dir = tempDir(t);
805	  const df = join(dir, 'data.json');
806	  addResource(df, '会议室');
807	
808	  const fOld = writeIcal(dir, 'old.ics', ical(event('old-solo', '20261005T080000', '20261005T090000')));
809	  importOk(df, fOld, ['R0001'], '先导入一个独立事件');
810	
811	  const f = writeIcal(dir, 'mix.ics', ical(
812	    event('old-solo', '20261005T080000', '20261005T090000'), // 重放
813	    event('new-solo', '20261006T080000', '20261006T090000'),
814	    event('new-weekly', '20261102T090000', '20261102T100000', 'RRULE:FREQ=WEEKLY;COUNT=2\n'),
815	  ));
816	  const r = importOk(df, f, ['R0001'], '混合导入');
817	  assert.match(r.stdout, /新增 2 项，重放 1 项/);
