        'UID:weekly-ex\n' +
        'DTSTART:20261005T100000\n' +
        'DTEND:20261005T110000\n' +
        'RRULE:FREQ=WEEKLY;COUNT=4\n' +
        'EXDATE:20261012T100000,20261019T100000\n' +
        'EXDATE:20261012T100000\n' +
        'END:VEVENT\n',
    ),
  );
