): Map<string, {start: string; end: string}> =>
  new Map(list.map((x) => [x.recurrenceId, {start: x.start, end: x.end}]));
const sameExceptions = (
  a: Array<{recurrenceId: string; start: string; end: string}>,
  b: Array<{recurrenceId: string; start: string; end: string}>,
): boolean => {
